import hashlib
import importlib.util
import json
from pathlib import Path
import tempfile
import unittest
import zipfile

spec = importlib.util.spec_from_file_location('separate_l4n_release', Path(__file__).parents[1] / 'scripts/separate_l4n_release.py')
module = importlib.util.module_from_spec(spec)
spec.loader.exec_module(module)


class ReleasePackaging(unittest.TestCase):
    def package(self, directory, name, plugin=b'plugin fixture'):
        path = directory / name
        files = {'bin/dxvk_d3d9.dll': b'client fixture', 'custom.txt': b'preserve text'}
        if plugin is not None:
            files['optional/L4N/L4D2BridgePlugin.dll'] = plugin
        hashes = {name: hashlib.sha256(data).hexdigest() for name, data in files.items()}
        files['SHA256.json'] = json.dumps(hashes).encode()
        files['BUILD-INFO.json'] = json.dumps({'version': '1.2.0-dev.1', 'build_id': 'matching-build', 'source_commit': 'matching-source', 'files': hashes}).encode()
        with zipfile.ZipFile(path, 'w') as archive:
            for relative, data in files.items():
                archive.writestr(path.stem + '/' + relative, data)
        return path

    def test_separate_component_preserves_inputs_and_core(self):
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            inputs = [self.package(root, 'full.zip'), self.package(root, 'patch.zip')]
            originals = [path.read_bytes() for path in inputs]
            output = module.separate(inputs, root / 'release', '1.2.0-dev.1')
            self.assertEqual(len(output), 3)
            self.assertEqual([path.read_bytes() for path in inputs], originals)
            for path in output[:2]:
                with zipfile.ZipFile(path) as archive:
                    self.assertFalse(any(name.endswith('L4D2BridgePlugin.dll') for name in archive.namelist()))
                    self.assertEqual(archive.read(path.stem + '/bin/dxvk_d3d9.dll'), b'client fixture')
                    self.assertEqual(archive.read(path.stem + '/custom.txt'), b'preserve text')
                    receipt = json.loads(archive.read(path.stem + '/BUILD-INFO.json'))
                    manifest = json.loads(archive.read(path.stem + '/SHA256.json'))
                    self.assertFalse(receipt['optional_plugin'])
                    self.assertEqual(receipt['files'], manifest)
                    self.assertNotIn('optional/L4N/L4D2BridgePlugin.dll', manifest)
            with zipfile.ZipFile(output[-1]) as archive:
                prefix = output[-1].stem
                self.assertEqual(archive.read(prefix + '/bin/neko/plugins/L4D2BridgePlugin.dll'), b'plugin fixture')
                self.assertFalse(any('dxvk_d3d9' in name for name in archive.namelist()))

    def test_mismatched_plugins_fail_before_output(self):
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            inputs = [self.package(root, 'full.zip'), self.package(root, 'patch.zip', b'different')]
            with self.assertRaisesRegex(ValueError, 'Mismatched L4N'):
                module.separate(inputs, root / 'release', '1.2.0-dev.1')
            self.assertFalse((root / 'release').exists())

    def test_no_plugin_never_invents_component(self):
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            path = self.package(root, 'full.zip', None)
            output = module.separate([path], root / 'release', '1.2.0-dev.1')
            self.assertEqual(len(output), 1)


if __name__ == '__main__':
    unittest.main()
